        static float Row(int shell,int kind,int row,float v) {
            float result=0;
            foreach(var f in Features)if(f.shell==shell&&f.kind==kind&&f.row==row) {
                float outside=Mathf.Max(f.span.x-v,v-f.span.y);
                float weight=1-Mathf.SmoothStep(0,1,Mathf.InverseLerp(0,.045f,outside));
                if(kind==1){float center=(f.span.x+f.span.y)*.5f,radius=Mathf.Max(.012f,(f.span.y-f.span.x)*.5f);weight=Mathf.Exp(-.5f*Mathf.Pow((v-center)/radius,2));}
                result=Mathf.Max(result,weight);
            }
            return result;
        }
        static float Coverage(int shell,int kind,float t,float v) {
