            float fade=Coverage(shell,0,t,v),core=Coverage(shell,1,t,v);Color color;
            if(shell%2==0) {color=Color.Lerp(Hex("333F88"),Hex("6976AC"),fade*.20f);color=Color.Lerp(color,Hex("B7BFEB"),core*.58f);}
            else {color=Color.Lerp(Hex("6976AC"),Hex("CED6EA"),Mathf.Max(fade*.40f,core*.80f));}
            float edge=1-Mathf.SmoothStep(0,1,Mathf.InverseLerp(.003f,.024f,Mathf.Min(v,1-v)));
            return Color.Lerp(color,Hex("233150"),edge*.55f);
        }
        public static bool ContainsUV(Vector2 st) {Vector2 p=new Vector2(st.x*1024,st.y*2048);foreach(var o in Origins)if(p.x>=o.x&&p.x<=o.x+Width&&p.y>=o.y&&p.y<=o.y+Height)return true;return false;}
        public static Vector2Int Origin(int shell)=>Origins[shell];
        public static Vector2 UV(int shell,float t,float v)=>new Vector2((Origins[shell].x+4+120*t)/1024f,(Origins[shell].y+4+56*v-128)/1024f);
    }
}
